    /**
     * R :: Content Pending.
     *
     * @return
     * @access private
     *
     */
    function alternating_row_style($row_id)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * 5 :: Tuesday, August 11, 2026 @ 2257 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, alternating_row_style,
         * from crnrstn to the crnrstn_registry_user.
         * 5 :: Tuesday, August 25, 2026 @ 0329 hrs.
         *
         */

        $R_style_data = \func_get_args();

        if(!isset(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id])){

            $input_cnt = \sizeof($R_style_data);
            self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_cnt'] = $input_cnt;

            for($i = 0; $i < (self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_cnt']); $i++)
            {

                // Skip the $row_id data.
                if($i == 0) continue;

                // Initialize all row style data.
                self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][] = $R_style_data[$i];

            }

            // Set current style.
            self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_current'] = 0;

            self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_cnt'] = \count(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data']);

            if(\strlen(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][0]) > 0)
                return ' ' . self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][0];

            return self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][0];

        }else{

            for($i = 0; $i < self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_cnt']; $i++){

                if(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_current'] != $i)
                    $current_style = $i;

                if((self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_current'] != $i) &&
                    isset(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i]))
                {

                    self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_current'] = $i;

                    if(\strlen(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i]) > 0)
                        return ' ' . self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i];

                    return self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i];

                }

            }

            // Loop through the row styles...again...for a match.
            for($i = 0; $i < self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_cnt']; $i++){

                if($i == 0) continue;

                if(isset($current_style))
                    if(($i != $current_style))
                    {

                        self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_current'] = $i;

                        if(\strlen(self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i]) > 0)
                            return self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i];

                        return self::$R_data['dom_support']['row_style'][self::$R_data['R_cluster_id']][$row_id]['style_data'][$i];

                    }

            }

        }

    }

    /**
     * R :: Content pending.
     *
     * @param
     * @return
     * @access public
     *
     */
    function file_url_cache_id($file_path)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, file_url_cache_id,
         * from crnrstn to the crnrstn_registry_user.
         * 5 :: Tuesday, August 25, 2026 @ 0342 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Renamed the
         *       crnrstn->resource_filecache_version
         *       method to
         *       file_url_cache_id($file_path),
         *       and updated all CLR-SSL framework
         *       resources accordingly (16 files in
         *       total will have been reviewed by the
         *       completion of this update).
         *       5 :: Sunday, July 26, 2026 @ 0404 hrs.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * SOURCE  :: https://www.php.net/manual/en/function.filesize.php
         * COMMENT :: https://www.php.net/manual/en/function.filesize.php#121370
         * AUTHOR  :: ivijan dot stefan at gmail dot com
         *
         * This function also can be great for browser
         * caching controll. For example, you have a
         * stylesheet and you want to make sure everyone
         * has the most recent version. You could rename
         * it every time you edit it, but that would be
         * a waste of time.
         *
         * Instead, you can do like:
         *
         * echo '<link rel="stylesheet" href="style.css?ver=1.' .
         *      filesize(dirname(__FILE__) . '/style.css') . '.' .
         *      filemtime(dirname(__FILE__).'/style.css') .
         *      '.0">';
         *
         * Sample output:
         *
         *      <link rel="stylesheet" href="style.css?ver=1.8824.1499869132.0">
         *
         *      This also can be apply for JS and also images with same name.
         *
         */
        $file_cache_version_str = '420.' .
                                  \filesize($file_path) . '.' .
                                  \filemtime($file_path) .
                                  '.0';

        return $file_cache_version_str;

    }

