         *
         *
         * 5 :: Wednesday, May 27, 2026 @ 0034 hrs.
         *
         */

        switch($caller){
            case __NAMESPACE__ . '\_crnrstn_native_resource_registry':

                switch($request_type){
                    case 'CRNRSTN_FILE_NOT_FOUND[new_obj_exe]':

                        if(isset(self::$_R['kivotos']->R['xml'])){

