                                                [Wed Jun 10 01:42:04.165931 2026] [:error] [pid 25929] [client 172.16.225.1:55270]
                                                [lnum 7088] [mthd CRNRSTN\\crnrstn::springs_of_Elim]
                                                $caller[CRNRSTN\\_crnrstn_native_resource_registry].
                                                $request_type[CRNRSTN_FILE_NOT_FOUND[new_obj_exe]].

                                                [Wed Jun 10 01:42:04.165967 2026] [:error] [pid 25929] [client 172.16.225.1:55270]
                                                [lnum 7094] [mthd CRNRSTN\\crnrstn::springs_of_Elim]
                                                $version_crnrstn[2.00.0001].

