    private function initialize_application_folders(
                     $application_directory, 
                     $R_framework_directory, 
                     $R_hmac_algorithm_override)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Created the method, initialize_application_folders(), 
         *       in the class definition of The Lightbox Helper 
         *       by eVifweb® 
         *       5 :: Wednesday, August 7, 2024 @ 0344 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, initialize_application_folders(), 
         * to crnrstn_registry_user from crnrstn.
         * 5 :: Tuesday, May 26, 2026 @ 2030 hrs.
         *
         */

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize the application 
         * directory, framework 
         * directory, HMAC Algorithm,
         * and CLR-SSL Debug Mode
         * private static variables. 
         *
         */
        self::$R_data['application_directory'] = $application_directory;

        if(isset($R_framework_directory))
            self::$R_data['R_framework_directory'] = $R_framework_directory;

        self::$R_data['R_framework_path'] = $this->return_root(
                                                   NULL,
                                                   NULL,
                                                   $R_framework_directory);

        if(isset($R_hmac_algorithm_override))
            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * TODO :: Input validation that honors 
             *         hash availability on the server. 
             *         5 :: Wednesday, August 7, 2024 @ 0423 hrs.
             *
             *
             */
            self::$R_data['hmac_algorithm']           = $R_hmac_algorithm_override;
        else
            self::$R_data['hmac_algorithm']           = $this->R_load_static(
                                                               __METHOD__, 
                                                               'hmac_algorithm');

        self::$R_data['string_concat_delimiter_char'] = $this->R_load_static(
                                                               __METHOD__, 
                                                               'string_concat_delimiter_char');

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Initialize a HEX color control 
         * driver for the creative 
         * directing of the CSS styles 
         * of system HTML text output. 
         *
         * The affected system resources 
         * include HTML content 
         * output from:
         *  - /_R/_config/
         *    _config.resource_registry/
         *    crnrstn.native_resource_registry.function.php
         *  - /_R/_config/
         *    _config.resource_registry/
         *    crnrstn.native_registered_resource_content_library.function.php
         *  - /_R/_config/
         *    config.integer_constants/
         *    crnrstn.system_integer_bank.function.php
         *  - /_R/_config/
         *    config.lightbox_helper.original/
         *  - /_R/_config/
         *    config.system_content/
         *    crnrstn.documentation_library.function.php
         *  - /_R/_config/
         *    config.system_links/
         *    crnrstn.system_link_library.function.php
         *
         *
         * 5
         *
         * Saturday, August 24, 2024 @ 0851 hrs.
         *
         * self::$background_color_hex = $background_color_hex;
         *
         */
        self::$R_data['background_color_hex'] = $this->R_load_static(
                                                       __METHOD__, 
                                                       'background_color_hex');

    }

    /**
     * R :: Return the CLR-SSL framework path root.
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function return_root(
        $system_path = NULL,
        $application_directory_override = NULL,
        $R_framework_directory_override = NULL)
    {
        // 5 :: Saturday, August 1, 2026 @ 1631 hrs.

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Variable Initialization.
         *
         */
        $root              =
        $crnrstn_file_path = NULL;

        if(!isset($application_directory_override))
            $application_directory = self::$R_data['application_directory'];
        else
            $application_directory = $application_directory_override;

        if(!isset($R_framework_directory_override))
            $R_framework_directory= self::$R_data['R_framework_directory'];
        else
            $R_framework_directory = $R_framework_directory_override;

        $directory_shift  =
        $path_chunk       = array();

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Evaluate $application_directory for
         * any change directory input commands.
         *
         * Happy birthday to you, J5, my boy!
         * 11/11/2005 - 08/16/2021 @ 0345 hrs.
         *
         *
         * 5 :: Tuesday, November 11, 2025 @ 2111 hrs.
         *
         */
        if((\strpos($application_directory, '../') !== false) ||
            ($application_directory == ''))
        {

            if(isset($system_path))
                $script_filename = \str_replace(
                    self::$R_data['operating_system']['R_path_patterns'][0],
                    self::$R_data['operating_system']['R_path_replacements'][0],
                    $system_path);
            else
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Standardize the use of
                 * directory separator based
                 * on path replacement
                 * patterns specific to the
                 * server operating system.
                 *
                 *
                 * 5
                 *
                 */
                $script_filename = \str_replace(
                    self::$R_data['operating_system']['R_path_patterns'][0],
                    self::$R_data['operating_system']['R_path_replacements'][0],
                    $_SERVER['SCRIPT_FILENAME']);
            $script_filepath_ARRAY  = \explode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filename);
            $app_directory          = \explode('../', $application_directory);
            $change_directory_depth = \sizeof($app_directory);

            for($i = 0; $i < $change_directory_depth; $i++){

                $tmp_data          = \array_pop($script_filepath_ARRAY);
                $app_dir_chunk     = \array_pop($app_directory);
                $directory_shift[] =  '../';

                if(($app_dir_chunk != '..') &&
                    ($app_dir_chunk != '.'))
                    $path_chunk[] = $app_dir_chunk;

            }

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Remove one "../" directory shift,
             * and then convert (implode) the
             * $directory_shift array into
             * string data.
             *
             *
             * 5 :: Case of the Monday's, August 3, 2026 @ 0545 hrs.
             *
             * Lights off a surpassingly
             * righteous rip on the bong
             * with fire from the kitchen
             * stove gas range.
             * Sips coffee.
             *
             */
            $tmp_data                        = \array_pop($directory_shift);
            self::$R_data['directory_shift'] = \implode('', $directory_shift);

            if(\strlen($path_chunk[0]) > 0)
                self::$R_data['directory_shift'] .= $path_chunk[0];

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of HTTP
             * forward slashes by removing
             * any trailing slash.
             *
             *
             * 5
             *
             */
            self::$R_data['directory_shift'] = \rtrim(self::$R_data['directory_shift'], '/');

            if(\strlen($path_chunk[0]) > 0)
                $root = \implode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filepath_ARRAY) .
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    $path_chunk[0] .
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    $R_framework_directory;
            else
                $root = \implode(self::$R_data['operating_system']['os_path_dir_separator_char'], $script_filepath_ARRAY) .
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    $R_framework_directory;

            $root = \str_replace(
                self::$R_data['operating_system']['R_path_patterns'][0],
                self::$R_data['operating_system']['R_path_replacements'][0],
                $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of the
             * operating system specific
             * directory separator by
             * reducing all double slashes
             * to single.
             *
             *
             * 5
             *
             */
            while(\strpos($root,
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    self::$R_data['operating_system']['os_path_dir_separator_char']) !== false)
                $root = \str_replace(self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    self::$R_data['operating_system']['os_path_dir_separator_char'],
                    self::$R_data['operating_system']['os_path_dir_separator_char'],
                    $root);

        }

        if(!isset($root)){

            $root = $_SERVER['DOCUMENT_ROOT'] .
                \DIRECTORY_SEPARATOR .
                $application_directory .
                \DIRECTORY_SEPARATOR .
                $R_framework_directory .
                \DIRECTORY_SEPARATOR;

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of
             * directory separator based
             * on path replacement
             * patterns specific to the
             * server operating system.
             *
             *
             * 5
             *
             */
            $root = \str_replace(
                self::$R_data['operating_system']['R_path_patterns'][0],
                self::$R_data['operating_system']['R_path_replacements'][0],
                $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Standardize the use of the
             * operating system specific
             * directory separator by
             * reducing all double slashes
             * to single.
             *
             *
             * 5
             *
             */
            while(\strpos($root,
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    self::$R_data['operating_system']['os_path_dir_separator_char']) !== false)
                $root = \str_replace(
                    self::$R_data['operating_system']['os_path_dir_separator_char'] .
                    self::$R_data['operating_system']['os_path_dir_separator_char'],
                    self::$R_data['operating_system']['os_path_dir_separator_char'],
                    $root);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Remove trailing
             * slash.
             *
             */
            $root = $this->strrtrim(
                $root,
                self::$R_data['operating_system']['os_path_dir_separator_char']);

        }

        return $root;

    }

    /**
     * R :: Retrieve and return cold static CLR-SSL data. 
     *
     * @param
     * @return
     * @access private
     *
     */
    private function R_load_static(
                     $caller,
                     $resource)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Created R_load_static() method 
         *       within crnrstn.
         *       5 :: Tuesday, March 31, 2026 @ 2159 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, R_load_static(), 
         * to crnrstn_registry_user from crnrstn. 
         * 5 :: Tuesday, May 26, 2026 @ 2029 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added a $caller input parameter 
         *       to the crnrstn_registry_user 
         *       R_load_static() method. 
         *       5 :: Tuesday, June 16, 2026 @ 1141 hrs.
         *
         */

        // Initialize $R_data. 
        $R_data = '';

        // 5 :: Tuesday, June 16, 2026 @ 1227 hrs.
        $read_access_denied = false;

        switch($resource){
            case 'R_timezone_default':
                // 5 :: Monday, August 10, 2026 @ 1000 hrs.

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Include and evaluate 
                 * the system file to receive
                 * and return $R_data. 
                 *
                 * /_R/_config/_config.defaults
                 * /load_static_cache/R_timezone_default
                 * /crnrstn.R_timezone_default.runtime_exe.php
                 *
                 *
                 *
                 * 5 :: Monday, August 10, 2026 @ 1011 hrs.
                 *
                 */
                $read_authorized_callers = array(__NAMESPACE__ . 
                                               '\crnrstn::R_data_write' => 1, __NAMESPACE__ .
                                               '\crnrstn_registry_user::R_data_write' => 1);

                if(!isset($read_authorized_callers[$caller])){
                    // 5 :: Tuesday, June 16, 2026 @ 1231 hrs.

                    $read_access_denied = true;

                    break 1;

                }

                $resource_filename = 'crnrstn.' . $resource . 
                                     '.runtime_exe.php';
                $resource_filepath = self::$R_data['R_framework_path'] . self::$R_data['operating_system']['os_path_dir_separator_char'] .
                                     '_config' . self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                                     '_config.defaults' . self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                                     'load_static_cache' . self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                                     $resource . self::$R_data['operating_system']['os_path_dir_separator_char'] . 
                                     $resource_filename;

                if($this->is_file($resource_filepath, $resource_filename)){

                    // Load $R_data into memory.
                    require($resource_filepath);

                }else{

                    $clr_ssl_msg = 'Data request failed. Cannot ' . 
                                   'evaluate missing system file: ' .
                                   $resource_filepath . 
                                   ' Default data will manually be ' . 
                                   'loaded by CRNRSTN ::';
                    // 5 :: Sunxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx
                    $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                                 'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
                    $token = array(
                             'token'                   => $msg_token, 
                             'token_generation_date'   => $token_generation_date, 
                             'request_type'            => __METHOD__, 
                             'code'                    => 200, 
                             'clr_ssl_msg'             => $clr_ssl_msg);
                    $this->error_log(
                           $clr_ssl_msg, 
                           \LOG_CRIT, 
                           \E_ERROR, 
                           __LINE__, 
                           __METHOD__, 
                           __FILE__, 
                           $token);

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Gracefully degrade with 
                     * a manual initialization of 
                     * default $R_data here. 
                     *
                     * We try to set the timezone 
                     * here, first.
                     * -----
                     * /_R/_config/_config.defaults
                     * /load_static_cache/R_timezone_default
                     * /crnrstn.R_timezone_default.runtime_exe.php
                     *
                     * # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * The return data is a timezone identifier, 
                     * like UTC, Africa/Lagos, Asia/Hong_Kong, 
                     * or Europe/Lisbon. The list of valid 
                     * identifiers is available.
                     *
                     * Please see the list of supported 
                     * timezone identifiers:
                     * https://www.php.net/manual/en/timezones.php
                     *
                     *
                     * 5 :: Monday, August 10, 2026 @ 1012 hrs.
                     *
                     */
                    $R_data = self::$R_data['R_timezone'];

                }

            break;
            case 'R_seo_analytics':
                // 5 :: Wednesday, August 12, 2026 @ 1133 hrs.

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Include and evaluate
                 * the system file to receive
                 * and return $R_data.
                 *
                 * /_R/_config/_config.defaults
                 * /load_static_cache/R_seo_analytics
                 * /crnrstn.R_seo_analytics.runtime_exe.php
                 *
                 *
                 *
                 * 5 :: Wednesday, August 12, 2026 @ 1134 hrs.
                 *
                 */
                $read_authorized_callers = array(__NAMESPACE__ .
                                               '\crnrstn::R_data_write' => 1, __NAMESPACE__ .
                                               '\crnrstn_registry_user::R_data_write' => 1);

                if(!isset($read_authorized_callers[$caller])){

                    $read_access_denied = true;

