    /**
     * R :: Return report metrics on cold static CLR-SSL data. 
     *
     * @param
     * @return
     * @access public
     *
     */
    function R_sync(
             $resource_name, 
             $resource_data, 
             &$R_data_000, &$R_data_001 = NULL, 
             &$R_data_002 = NULL, &$R_data_003 = NULL, 
             &$R_data_004 = NULL, &$R_data_005 = NULL, 
