    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function session_runtime(
             $reporting_mode = CRNRSTN_FLOAT, 
             $finite_express_mode = 'ELAPSED', 
             $decimal = 8)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the method, session_runtime(), 
         * to crnrstn_registry_user from crnrstn. 
         * 5 :: Tuesday, May 26, 2026 @ 2024 hrs.
         *
         */

        if(\is_string($reporting_mode))
            $reporting_mode = self::$R_data['int_flag'][$reporting_mode];

        if(isset(self::$_R['kivotos']->R['session_mgr']))
            return self::$_R['kivotos']->R['session_mgr']->session_runtime(
                                                           $reporting_mode,
                                                           $finite_express_mode,
                                                           $decimal);

        if(!isset($_SESSION['R_cluster_id_starttime']))
            $_SESSION['R_cluster_id_starttime'] = $this->microtime_float();

        $tmp_mirco_time_float = $this->microtime_float();
        $timediff             = $tmp_mirco_time_float - $_SESSION['R_cluster_id_starttime'];
        $len                  = $decimal * -1;

        switch($reporting_mode){
            case self::$R_data['int_flag']['R_string']:

                return $this->incarnate($finite_express_mode, $timediff, true);

            break;
            case self::$R_data['int_flag']['R_float']:
            case self::$R_data['int_flag']['R_double']:

                if(self::$R_data['operating_system']['name'] == 'Windows®')
                    return (double) $timediff;

                return \substr($timediff, 0, $len);

            break;
            case self::$R_data['int_flag']['R_int']:
            case self::$R_data['int_flag']['R_integer']:
            default:

                if(self::$R_data['operating_system']['name'] == 'Windows®')
                    return (int) $timediff;

                return \substr($timediff, 0, $len);

            break;

        }

    }

