    /**
     * R :: Content pending. 
     *
     * @return
     * @access public
     *
     */
    function is_ssl()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method was copied
         * from The Lightbox Helper
         * by eVifweb®
         * 5 :: Wednesday, August 7, 2024 @ 2345 hrs.
         *
         */
        if(!empty($_SERVER['HTTPS']) && 
            ($_SERVER['HTTPS'] != 'off'))
        {

            $this->is_SSL = true;
            return true;

        }

        if(!empty($_SERVER['HTTP_X_FORWARDED_PROTO']) && 
            ($_SERVER['HTTP_X_FORWARDED_PROTO'] == 'https'))
        {

            $this->is_SSL = true;
            return true;

        }

        $this->is_SSL = false;

        return false;

    }

