    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function hash_file(
             $file_path = NULL, 
             $algorithm_override = NULL, 
             $binary = false, 
             $runtime_acceleration = false, 
             $session_acceleration_key = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Method copied from 
         * The Lightbox Helper 
         * by eVifweb®
         *
         *
         * 5 :: Wednesday, August 7, 2024 @ 0648 hrs.
         *
         */

        if(isset(self::$_R['registry_assistant'])){

            return self::$_R['registry_assistant']->hash_file(
                                                    $file_path, 
                                                    $algorithm_override, 
                                                    $binary, 
                                                    $runtime_acceleration, 
                                                    $session_acceleration_key);

        }

        $tmp_key = 'CRNRSTN_SESSION_ACCELERATED::' . $session_acceleration_key;

        if(isset($session_acceleration_key) && !isset($file_path)){

            if($this->isset_resource('data_value', $tmp_key, 'CRNRSTN::RESOURCE::HASH_ACCELERATION') == true){

                return $this->get_resource($tmp_key, 0, 'CRNRSTN::RESOURCE::HASH_ACCELERATION');

            }

        }else{

            if(isset($session_acceleration_key)){

                if($this->isset_resource('data_value', $tmp_key, 'CRNRSTN::RESOURCE::HASH_ACCELERATION') == true){

                    return $this->get_resource($tmp_key, 0, 'CRNRSTN::RESOURCE::HASH_ACCELERATION');

                }

                if(strlen($file_path) > 0){

                    if(is_file($file_path)){

                        //$tmp_date_lastmodified = filemtime($file_path);

                        $tmp_hash_val = $this->hash_file($file_path, $algorithm_override, $binary);

                        //
                        // TODO :: Get this behind
                        //         session channel.
                        //
                        // This data should be
                        // handled through the
                        // CRNRSTN :: Lightsaber
                        // SOAP Services Layer
                        // Multi-Channel Decoupled
                        // Data Object (MC-DDO),
                        // as it is with
                        // config info.
                        //
                        // This is an early use
                        // of what has now
                        // become the CRNRSTN ::
                        // Lightsaber MC-DDO
                        // application architecture.
                        //
                        // $this->add_ssdtla_resource($tmp_key, $tmp_hash_val, NULL, CRNRSTN_AUTHORIZE & CRNRSTN_CHANNEL_SESSION);

                        //
                        // The CRNRSTN :: Lightsaber RoCEv2 SOAP
                        // Services Layer Multi-Channel
                        // Decoupled Data Object (MC-DDO)
                        // Data Storage Services Layer.
                        //
                        //
                        // 5
                        //
                        // # C # R # N # R # S # T # N # :: # L # I # G # H # T
                        // CRNRSTN :: UGC DATA INPUT [HASH ACCELERATION]
                        $tmp_output = $this->add_resource($tmp_key, $tmp_hash_val, 'CRNRSTN::RESOURCE::HASH_ACCELERATION', CRNRSTN_SETTINGS_CRNRSTN, 0);

                        return $tmp_hash_val;

                    }

                }

                return '';

            }

        }

        //
        // The "files processed" hash
        // versioning (in memory)
        // hash_acceleration_array is
        // dual-keyed on file size
        // and date last modified.
        //
        // TODO :: Remove this todo
        //         when Windows
        //         compatibility testing
        //         is complete.
        //         Friday, December 1, 2023 @ 0953 hrs.
        //
        $tmp_filesize = filesize($file_path);
        $tmp_date_lastmodfied = filemtime($file_path);

        //
        // Load the CRNRSTN ::
        // Lightsaber SOAP
        // Services Layer
        // system default
        // hashing algorithm.
        //
        //
        // 5
        if(!isset($algorithm_override)){

            //$algorithm_override = self::$hmac_hash_algorithm_ARRAY['options']['server'][self::$hmac_hash_algorithm_ARRAY['DEFAULT'][CRNRSTN_INTEGER]];
            $algorithm_override = self::$hmac_hash_algorithm_ARRAY['DEFAULT']['NAME'];

        }

        //
        // INITIALIZE BYTE COUNT BY HASH.
        if(!isset($this->total_bytes_hashed_ARRAY[$algorithm_override])){

            $this->total_bytes_hashed_ARRAY[$algorithm_override] = 0;

        }

        //
        // THE FILE SIZE AND LAST MODIFIED DATE MUST BE
        // UNCHANGED IN ORDER FOR APPLICATION ACCELERATION
        // TO FIRE.
        if($runtime_acceleration == true){

            if(isset($this->hash_acceleration_ARRAY[$file_path][$tmp_date_lastmodfied][$tmp_filesize])){

                //error_log(__LINE__ . ' crnrstn HOT RUNTIME STRAIGHT RETURN [' . $this->hash_acceleration_ARRAY[$file_path][$tmp_date_lastmodfied][$tmp_filesize] . '].');
                return $this->hash_acceleration_ARRAY[$file_path][$tmp_date_lastmodfied][$tmp_filesize];

            }

        }

        $this->total_bytes_hashed_ARRAY[$algorithm_override] += $tmp_filesize;
        $tmp_hash_val = hash_file($algorithm_override, $file_path, $binary);

        //
        // TRACK ACCESSED CONFIGURATION FILES BY
        // THE ACQUIRED FILE VERSIONING HASH.
        self::$server_files_version_hash_ARRAY[$file_path] = $tmp_hash_val;

        //error_log(__LINE__ . ' crnrstn **SLOW** HASH RETURN algorithm[' . $algorithm_override . ']. hash_val[' . $tmp_hash_val . ']. [' . $file_path . '].');

        if($runtime_acceleration == true){

            //error_log(__LINE__ . ' crnrstn **NEUTRAL** HASH RUNTIME STORE [' . $tmp_hash_val . '].');
            $this->hash_acceleration_ARRAY[$file_path][$tmp_date_lastmodfied][$tmp_filesize] = $tmp_hash_val;

        }

        return $tmp_hash_val;

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function add_resource(
             $data_key, 
             $data_value = NULL, 
             $data_type_family = 'CRNRSTN::RESOURCE', 
             $data_authorization_profile = 'R_authorize & R_channel_RUNTIME',
             $index = NULL, 
             $ttl = 60, 
             $spool_resource = false, 
             $env_key = NULL)
    {

        if(\is_string($data_authorization_profile) ||
            !isset($data_authorization_profile))
        {

            switch($data_authorization_profile){
                case 'R_authorize & R_channel_RUNTIME':
                default:

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Convert CLR-SSL channel
                     * data to integer.
                     *
                     *
                     * 5 :: Monday, July 13, 2026 @ 0357 hrs.
                     *
                     */
                    $data_authorization_profile = self::$R_data['int_flag']['R_authorize'] &
                                                  self::$R_data['int_flag']['R_channel_RUNTIME'];

                break;

            }

        }

        if(isset(self::$_R['registry_assistant']))
            return self::$_R['registry_assistant']->add_resource(
                                                    $data_key,
                                                    $data_value,
                                                    $data_type_family,
                                                    $data_authorization_profile,
                                                    $index,
                                                    $ttl,
                                                    $spool_resource,
                                                    $env_key);

        //
        // This will hopefully be a
        // light-to-full-bore variation
        // of the CRNRSTN :: Lightsaber
        // SOAP Services Multi- Channel
        // Decoupled Data Object
        // (MC-DDO) data storage
        // services layer.
        //
        // [UPDATE] We need to put 100% of the
        //          CRNRSTN :: Lightsaber MC-DDO into
        //          The Lightbox Helper
        //          by eVifweb
        //          5 :: Thursday, July 11, 2024 @ 0430 hrs.
        //
        //
        // 5
        //
        // Friday, July 5, 2024 @ 0358 hrs.

        try{

            if(!isset($env_key)){

                $env_key = $this->return_env_key();

            }

            $tmp_stripe_key_ARRAY = $this->return_stripe_key_ARRAY('$env_key', '$data_key');
            $tmp_param_err_str_ARRAY = $this->return_regression_stripe_ARRAY('MISSING_STRING_DATA', $tmp_stripe_key_ARRAY, $env_key, $data_key);

            $tmp_param_missing_str = $tmp_param_err_str_ARRAY['string'];
            $tmp_param_missing_ARRAY = $tmp_param_err_str_ARRAY['index_array'];

            //if(count($tmp_param_missing_ARRAY) > 0){
            if(!!$tmp_param_missing_ARRAY){

                $this->error_log('Attempted ' . __METHOD__ . '(' .
                $data_key . ') but missing required parameters. ' .
                $tmp_param_missing_str, __LINE__, __METHOD__, __FILE__, CRNRSTN_SETTINGS_CRNRSTN);

                throw new \Exception('CRNRSTN :: initialization ERROR :: define_env_resource was called, ' .
                'but it was missing parameter information and so was not able to be initialized. env_key and ' .
                'resourceKey are required. env_key[' . $env_key . '] resourceKey[' . $data_key . ']');

            }else{

                //
                // Did CRNRSTN :: receive UGC
                // configuration input data that
                // is assigned to the currently
                // detected environment?
                //
                // If not, run a bypass here in
                // order to receive a minor
                // performance acceleration boost.
                if($this->config_is_valid_detected_env($env_key, false) == true){

                    if(!isset(self::$env_key_config_ARRAY[self::$config_serial][self::$env_key_hash_config_ARRAY[self::$config_serial]])){

