            $method = 'file';

        }

        //error_log('[rtime ' . $tmp_exception_runtime . ' secs] [' . $method . ' ' . $tmp_exception_method . '] [lnum ' . $tmp_exception_linenum . '] ' . $tmp_exception_msg);
        $tmp_exception_output_str = $tmp_exception_systemtime . ' [rtime ' .
            $tmp_exception_runtime . ' secs] [' . $method . ' ' .
            $tmp_exception_method . '] [lnum ' .
            $tmp_exception_linenum . '] ' . $tmp_exception_msg;

        error_log($tmp_exception_output_str);

