    function is_resource_flag_data_array($data)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * This method was copied 
         * from The Lightbox Helper 
         * by eVifweb® 
         * 5 :: Thursday, August 8, 2024 @ 0127 hrs.
         *
         */

        foreach($data as $res => $flag){

            // Is the flag not
            // a clean integer flag?
            if(!is_int($flag)){

                //
                // Maybe the flag
                // is dirty.
                //
                // Is the data
                // even numeric?
                if(is_numeric($flag)){

                    //
                    // Ok.
                    //
                    // We have flag
                    // data, but it
                    // is just a
                    // dirty string
                    // or something.
                    $flag = (int) $flag * 1;

                    //
                    // We have array data
                    // that looks like:
                    //
                    // 'registry_name' => (int) flag
                    //
                    // Now the flag
                    // is dutty!
                    return true;

                }else{

                    //
                    // The flag data
                    // is not numeric.
                    //
                    // We will skip
                    // any $res checks
                    // to see if it is
                    // an index.
                    //
                    // Hopefully, $res
                    // is an index.
                    //
                    // Hopefully, we
                    // have array data
                    // that looks like:
                    //
                    // (int) index => 'registry_name'
                    //
                    //
                    // 5
                    //
                    // Wednesday, July 24, 2024 @ 2102 hrs.
                    return false;

                }

            }else{

                //
                // We have array data
                // that looks like:
                //
                // 'registry_name' => (int) flag
                //
                // The flag was
                // borne dutty!
                //
                //
                // 5
                //
                // Wednesday, July 24, 2024 @ 2104 hrs.
                return true;

            }

            //
            // Build concatenated
            // string of resource
            // names to flush the
            // boot resources to
            // runtime memory.
            //
            //
            // 5 :: Wednesday, July 24, 2024 @ 1851 hrs.
            $tmp_res_str .= $res . $tmp_str_concat_char;

        }

    }

