                         */

                        if($tmp_tidy_boolean !== false)
                            return 1;

                        return 0;

                    break;

                }

            break;
            case 'R_bool_is_html':
            case self::$R_data['int_flag']['R_bool_is_html']:

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
