    /**
     * R :: Generate a resource memory pointer for the CLR-SSL Resource Registry.
     * 
     *
     * @param
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function generate_memory_pointer(
             $resource_name, 
             $R_action = 'new', 
             $R_data_000 = NULL)
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Copied the method, generate_memory_pointer(),  
         *       to the crnrstn_registry_user 
         *       from crnrstn.
         *       5 :: Tuesday, May 26, 2026 @ 1907 hrs.
         *
         */

        switch($R_action){
            case 'dependency_ping':
                // 5 :: Saturday, April 25, 2026 @ 0223 hrs.

                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * Minimum token length = 64 bytes. 
                 * Maximum token length = 275 bytes. 
                 *
                 *
                 * 5 :: Saturday, April 25, 2026 @ 0229 hrs.
                 *
                 */
                if((strlen($R_data_000) > 63) && 
                    (strlen($R_data_000) < 276))
                {

                    return $R_data_000;

                }

            case 'new':
            default:

                return $this->generate_key(
                              'memory_pointer', 
                              $resource_name);

            break;

        }

    }

    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access public
     *
     */
    function generate_key(
             $key_name, 
             $salt = '')
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Added the generate_key method to crnrstn. 
         * 5 :: Thursday, April 30, 2026 @ 1424 hrs.
         *
         * # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Edit: Added the salt input to the 
         *       crnrstn->generate_key method for 
         *       support of CLR-SSL Resource 
         *       Registry memory pointers where 
         *       the hash uses a unique runtime 
         *       salt + datestamp for a weak 
         *       pointer, as the CLR-SSL framework 
         *       cannot generate good crypt keys 
         *       right at the start. 
         *       5 :: Tuesday, May 26, 2026 @ 0427 hrs.
         *
         */

        switch($key_name){
            case 'compound_ointment_spice_salt':
                // 5 :: Monday, June 8, 2026 @ 0216 hrs.

                return $this->generate_new_key(
                              64, 
                              -1, 
                              true, 
                              'md5');

            break;
            case 'token_log_serial':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * 5 :: Thursday, May 28, 2026 @ 1053 hrs.
                 *
                 */

                if(!isset(self::$R_data['R_datatype_master'])){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Graceful degredation. 
                     *
                     * The CLR-SSL framework 
                     * is not yet ready. 
                     *
                     *
                     * 5
                     *
                     */
                    return $this->generate_key(
                                  'memory_pointer_weak', 
                                  $salt);

                }

                return $this->generate_new_key(
                              64, 
                              -1, 
                              true);

            break;
            case 'memory_pointer_weak':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * 5 :: Tuesday, May 26, 2026 @ 0417 hrs.
                 * tosses empty beer can. 
                 * goes to kitchen to light joint. 
                 *
                 */

                return hash(
                           self::$R_data['hmac_algorithm'], 
                           $salt . $this->return_micro_time());

            break;
            case 'memory_pointer':
                /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                 * 5 :: Tuesday, May 26, 2026 @ 0418 hrs.
                 * hits joint. 
                 * Last Modified: Tuesday, May 26, 2026 @ 0439 hrs.
                 *
                 */

                if(!isset(self::$R_data['R_datatype_master'])){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Graceful degredation. 
                     *
                     * The CLR-SSL framework 
                     * is not yet ready. 
                     *
                     *
                     * 5
                     *
                     */
                    self::$R_data['resource_registry']['current_mem_pointer'] = $this->generate_key(
                                                                                       'memory_pointer_weak', 
                                                                                       $salt);
                    return self::$R_data['resource_registry']['current_mem_pointer'];

                }

                self::$R_data['resource_registry']['current_mem_pointer'] = $this->generate_new_key(
                                                                                   64, 
                                                                                   -1, 
                                                                                   true);
                return self::$R_data['resource_registry']['current_mem_pointer'];

            break;
            case 'system_message_token':
                // 5 :: Thursday, April 30, 2026 @ 1442 hrs.

                if(!isset(self::$R_data['R_datatype_master'])){

                    /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
                     * Graceful degredation. 
                     *
                     * The CLR-SSL framework 
                     * is not yet ready. 
                     *
                     *
                     * 5
                     *
                     */
                    return hash(
                           'sha512', 
                           $key_name . 
                           $this->return_micro_time());

                }

                return $this->generate_new_key(
                              256, 
                              -1, 
                              true, 
                              'sha512');

            break;
            case 'request_id':
                // 5 :: Thursday, April 30, 2026 @ 1443 hrs.

                return $this->generate_new_key(
                              42, 
                              -1, 
                              true, 
                              self::$R_data['hmac_algorithm']);

            break;
            case 'request_serial':
                // 5 :: Thursday, April 30, 2026 @ 1446 hrs.

                return $this->generate_new_key(
                              64, 
                              -3);

            break;
            case 'resource_registry_request_serial':
                // 5 :: Thursday, April 30, 2026 @ 1451 hrs.

                return $this->generate_new_key(
                              50, 
                              -2, 
                              true);

            break;
            case 'cache_bust':
                // 5 :: Thursday, April 30, 2026 @ 1451 hrs.

                return $this->generate_new_key(
                              50, 
                              -1, 
                              true);

            break;
            case 'session_config_salt':
                // 5 :: Wednesday, May 20, 2026 @ 0148 hrs.

                return $this->generate_new_key(
                              64, 
                              -2);

            break;
            case 'R_cluster_id':
                // 5 :: Tuesday, June 9, 2026 @ 1747 hrs.

                return $this->generate_new_key(
                              64, 
                              -1, 
                              true);

            break;
            default:
                // 5 :: Wednesday, May 20, 2026 @ 0144 hrs.

                return $this->generate_new_key(
                              128, 
                              -5);

            break;

        }

    }

