    /**
     * R :: Content pending.
     *
     * @return
     * @access private
     *
     */
    private function initialize_apache_profile()
    {
        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Copied the initialize_apache_profile()
         * method from the crnrstn class definition
         * to the crnrstn_registry_user.
         * 5 :: Sunday, August 23, 2026 @ 0402 hrs.
         *
         */

        $server_software         = \strtolower(\trim($_SERVER['SERVER_SOFTWARE']));
        $server_software_version = \explode('apache/', $server_software);
        $version                 = \explode('.', $server_software_version[1]);

        /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
         * Powered by APACHE 
         * image driver.
         *
         */
        if(isset($version[1]))
            self::$R_data['operating_system']['version_apache_sysimg'] = (double) $version[0] .
                                                                         '.' .
                                                                         $version[1];
        else
            self::$R_data['operating_system']['version_apache_sysimg'] = (double) $version[0];

        $patch     = '';
        $tmp_array = \str_split($version[2]);
        $tmp_size  = \sizeof($tmp_array);

        for($i = 0; $i < $tmp_size; $i++)
            if(\is_numeric($tmp_array[$i]))
                $patch .= $tmp_array[$i];
            else
                $i = $tmp_size + 1;

        if(\strlen($patch) > 0)
            self::$R_data['operating_system']['version_apache'] = $version[0] .
                                                                  '.' .
                                                                  $version[1] .
                                                                  '.' .
                                                                  $patch;
        else
            self::$R_data['operating_system']['version_apache'] = $version[0] .
                                                                  '.' .
                                                                  $version[1];

    }

