     * (e.g. for use with version_compare()) 
     * 
     * OPENSSL_VERSION_NUMBER is a 
     * numeric release version 
     * identifier for OpenSSL.
     * 
     * Syntax: MNNFFPPS: major 
     * minor fix patch status (HEX) 
     * 
     * The status nibble meaning: 
     * 
     *   0 => development, 
     *   1 to e => betas, 
     *   f => release 
     *
     * Examples: 
     * - 0x000906023 => 0.9.6b beta 3 
     * - 0x00090605f => 0.9.6e release 
     * - 0x1000103f  => 1.0.1c 
     *
     * @param OpenSSL version 
     * identifier as hex value 
     * $openssl_version_number.
     * 
     */
    /**
     * R :: Content pending. 
     *
     * @param
     * @param
     * @return
     * @access private
     *
     */
    private function initialize_openssl_profile(
                     $patch_as_number = false, 
                     $openssl_version_number = NULL)
    {

        if(!defined('OPENSSL_VERSION_NUMBER')){

            self::$R_data['operating_system']['openssl_version'] = '';

            return NULL;

        }

        if(\is_null($openssl_version_number)) 
            $openssl_version_number = \OPENSSL_VERSION_NUMBER;

        $openssl_numeric_identifier = \str_pad(
                                      (string) \dechex($openssl_version_number), 
                                      8, 
                                      '0', 
                                      \STR_PAD_LEFT);

        $openssl_version_parsed = array();
        $preg = '/(?<major>[[:xdigit:]])(?<minor>[[:xdigit:]][[:xdigit:]])(?<fix>[[:xdigit:]][[:xdigit:]])';
        $preg .= '(?<patch>[[:xdigit:]][[:xdigit:]])(?<type>[[:xdigit:]])/';

        \preg_match_all(
            $preg, 
            $openssl_numeric_identifier, 
            $openssl_version_parsed);

        if(!empty($openssl_version_parsed)){

            $alphabet = array(1  => 'a', 2  => 'b', 
                              3  => 'c', 4  => 'd', 
                              5  => 'e', 6  => 'f', 
                              7  => 'g', 8  => 'h', 
                              9  => 'i', 10 => 'j', 
                              11 => 'k', 12 => 'l', 
                              13 => 'm', 14 => 'n', 
                              15 => 'o', 16 => 'p', 
                              17 => 'q', 18 => 'r', 
                              19 => 's', 20 => 't', 
                              21 => 'u', 22 => 'v', 
                              23 => 'w', 24 => 'x', 
                              25 => 'y', 26 => 'z');

            self::$R_data['operating_system']['openssl_version']  = \intval($openssl_version_parsed['major'][0]) . 
                           '.';
            self::$R_data['operating_system']['openssl_version'] .= \intval($openssl_version_parsed['minor'][0]) . '.';
            self::$R_data['operating_system']['openssl_version'] .= \intval($openssl_version_parsed['fix'][0]);

            /* # C # R # N # R # S # T # N # :: # L # I # G # H # T
             * Ideal for 
             * text comparison. 
             *
             */
            $openssl_version_int_val = \intval($openssl_version_parsed['patch'][0]);

            if(!$patch_as_number && 
                \array_key_exists($openssl_version_int_val, $alphabet))
                /*error_log('[lnum 4097] [crnrstn] ' . 
                 *    'openssl_version :: ' . 
                 *    $openssl_version . ' + ' . 
                 *    $alphabet[intval($openssl_version_parsed['patch'][0])]);
                 *
                 */
                self::$R_data['operating_system']['openssl_version'] .= $alphabet[$openssl_version_int_val];
            else
                if($openssl_version_int_val != 0)
                    /* error_log('[lnum 4106] [crnrstn] ' . 
                     *     'openssl_version :: ' . 
                     *     $openssl_version . 
                     *     ' + ' . 
                     *     intval($openssl_version_parsed['patch'][0]));
                     */
                    self::$R_data['operating_system']['openssl_version'] .= '.' . $openssl_version_int_val;

        }

        $clr_ssl_msg = 'The OpenSSL version ' . 
                       'is initialized: ' . 
                       \strval(self::$R_data['operating_system']['openssl_version']);
        // 5 :: Mon May xxxxxxxxxxxxxxxxxxxxxxxxxxx
        $msg_token = 'd9c5ca131ab8615a1738c340cf44c4ff' . 
                     'xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token_generation_date = '2026xxxxxxxxxxxxxxxxxxxxxxxxxxx';
        $token = array(
                 'token'                   => $msg_token, 
                 'token_generation_date'   => $token_generation_date, 
                 'request_type'            => __METHOD__, 
                 'code'                    => 200, 
                 'clr_ssl_msg'             => $clr_ssl_msg);
        $this->error_log(
               $clr_ssl_msg, 
               \LOG_DEBUG, 
               \E_NOTICE, 
               __LINE__, 
               __METHOD__, 
               __FILE__, 
               $token, 
               true);

    }

