         */

        $lang_profile = array();
        $lang_profile['locale_identifier']       = 'en';
        //$lang_profile['region_variant']          = $region;
        //$lang_profile['factor_weighting']        = $weighting;
        $lang_profile['iso_language_nomination'] = 'English';
        $lang_profile['native_nomination']       = 'English';
        $lang_profile['iso_639-1_2002']          = 'en';
        $lang_profile['iso_639-2_1998']          = 'eng';
        $lang_profile['iso_639-3_2007']          = 'eng';
        $lang_profile['uri']                     = 'https://en.wikipedia.org/wiki/English_language';

        if(isset($lang_profile[$lang_attribute]))
            return $lang_profile[$lang_attribute];

        if(isset($lang_profile[\strtolower($lang_attribute)]))
            return $lang_profile[\strtolower($lang_attribute)];

        // Default return.
        return 'en';

    }

